/* ===== 組み立て ===== */
(function(){
 const pk=a=>a[Math.floor(Math.random()*a.length)];
 const build=(pl,ac)=>{
  const me=pk(ac.me),cl=pk(ac.close);
  const L=[['bg',pl.bg],['',pl.intro],['cast','a,b,c']];
  ac.open.forEach(r=>L.push(r.slice()));
  L.push(['cast','a,b,c,*'+(8+Math.floor(Math.random()*10))]);
  if(ac.ring){L.push(['fx','ring'],['hide','']);}
  else if(ac.fx)L.push(['fx',ac.fx]);
  ac.mid.forEach(t=>L.push(['',t]));
  L.push(['me',me],cl.slice(),['',pl.end]);
  return L;
 };
 HG_PLACES.forEach(pl=>HG_ACTS.forEach(ac=>{
  const ev={id:'gen_'+pl.id+'_'+ac.t,n:pl.n+'の'+ac.t,bg:pl.bg,min:3,gen:true,rew:ac.rew||{fav:2}};
  if(pl.m)ev.m=pl.m;
  /* 組み立ては、イベントが選ばれるたびに(毎回ちがう組み合わせで)行う */
  Object.defineProperty(ev,'lines',{enumerable:true,get(){return build(pl,ac)}});
  BIG_EVENTS.push(ev);
 }));
})();

