(function(){
 HC_SITS.forEach(s=>{
  const ev={id:s.id,n:s.n,bg:'harem_gen_'+s.id,min:3,gen:true,
   lines:[['bg','harem_gen_'+s.id],['',s.intro],['cast','a,b,c'],s.ask.slice()],
   ch:s.opts.map(o=>({l:o.l,p:o.p,ok:{t:o.ok,rew:{fav:3,st:{charm:1}}},ng:{t:o.ng,rew:{fav:2}}}))};
  BIG_EVENTS.push(ev);
 });
})();

/* ===== 組み立てイベントは、40% の確率でだけ選ぶ。魅力85以上は、もう1回、起きることがある ===== */
const _bigEvent0=bigEvent;
bigEvent=function(done){
 /* 候補を、一時的に「手書き」または「組み立て」に絞る */
 const all=BIG_EVENTS.slice(),gens=all.filter(e=>e.gen),hand=all.filter(e=>!e.gen);
 const useGen=Math.random()<HG_RATE;
 BIG_EVENTS.length=0;(useGen?gens:hand).forEach(e=>BIG_EVENTS.push(e));
 const back=()=>{BIG_EVENTS.length=0;all.forEach(e=>BIG_EVENTS.push(e))};
 try{return _bigEvent0(()=>{back();done&&done()})}catch(e){back();throw e}
};
const _keyEventMore=keyEvent;
keyEvent=function(done){
 _keyEventMore(()=>{
  if(S&&S.st&&S.st.charm>=HG_BONUS_CHARM&&Math.random()<HG_BONUS_P&&!S.fin){
   S.keN[S.t]=Math.max(0,(S.keN[S.t]||0)-1);
   return bigEvent(done);
  }
  done&&done();
 });
};


/* =====================================================================
   ハーレム要素の追加: ① ハーレム会議と「協定」 ② ハーレム旅行
   ■ ① ハーレム会議(協定)
     ハーレムが3人以上になると、3か月ごとに「ハーレム会議」が開かれます。女子たちが話しあって決めた「協定」の候補が3つ出るので、1つ選びます。
     協定は、月替わりごとに自動で効果が出ます(HG_PACTS)。同時に有効な数は「1 + ハーレム人数÷3」(最大6)。いっぱいのときは、いちばん古い協定が終わります。
     いま有効な協定は、スマホ「暦」アプリの先頭に出ます。
     協定を足す … HG_PACTS に {id,n,d:説明, f:()=>月替わりの効果(文字を返すとお知らせに出ます)} を足す。
   ■ ② ハーレム旅行
     ハーレムが5人以上で、春休み(3月)・夏休み(8月)・冬休み(12月)に、旅行に誘われます(同じ月の旅行は1回だけ)。行き先を選ぶ(費用あり)と、出発・道中・目的地・夜・帰り道の場面が流れます。
     全員の好感度と魅力が上がります。行き先は HG_TRIPS に足せます({id,n,cost,bg,arrive:[…],act:[…],night:[…]})。 */

const HG_PACTS=[
 {id:'nuke',n:'抜け駆け禁止協定',d:'毎月、全員の好感度が少し上がる',f:()=>{avail().forEach(h=>add(h.id,1));return ''}},
 {id:'rota',n:'お弁当当番表',d:'毎月、お弁当代が浮いて、おこづかい+¥5,000',f:()=>{S.money+=5000;return '【協定】お弁当当番表のおかげで、お弁当代が浮いた。 ¥5,000'}},
 {id:'study',n:'みんなで勉強会',d:'毎月、学力+1',f:()=>{const g=gainSt('study',1);return g?'【協定】みんなで勉強会。 学力+1':''}},
 {id:'run',n:'朝のランニング隊',d:'毎月、体力+1',f:()=>{const g=gainSt('sport',1);return g?'【協定】朝のランニング隊。 体力+1':''}},
 {id:'mode',n:'おしゃれ会議',d:'毎月、30%で魅力+1',f:()=>{if(Math.random()<.3){const g=gainSt('charm',1);return g?'【協定】おしゃれ会議で、新しい髪型を提案された。 魅力+1':''}return ''}},
 {id:'rest',n:'休息当番制',d:'毎月、疲れが1減る',f:()=>{if(S.f>0){S.f--;return '【協定】休息当番制。今月は、無理せず、ゆっくりできた。'}return ''}},
 {id:'photo',n:'撮影協定',d:'毎月、必ず自撮りに誘われる',f:()=>''},
 {id:'gift',n:'贈り物ローテーション',d:'毎月、30%でおこづかい+¥15,000',f:()=>{if(Math.random()<.3){S.money+=15000;return '【協定】贈り物ローテーションで、プレゼントが届いた。 ¥15,000'}return ''}},
 {id:'cheer',n:'応援団の当番',d:'毎月、ランダムな女子1人の好感度が+3',f:()=>{const g=avail();if(!g.length)return '';add(g[Math.floor(Math.random()*g.length)].id,3);return ''}},
 {id:'peace',n:'みんな仲良し憲章',d:'毎月、全員の好感度+1・疲れ-1',f:()=>{avail().forEach(h=>add(h.id,1));if(S.f>0)S.f--;return ''}}
];
const HG_SCENES=[
 [['','放課後の空き教室。机をぐるりと並べて、女子たちが、会議の準備をしていた。'],['a','「それでは、第{n}回、{K}を、そっと幸せにする会議を、はじめます」'],['b','「議題は、これからの、みんなの約束ごとについて、です！」']],
 [['','校舎の裏の、ひみつの集会所。ホワイトボードに、「協定」の二文字が、大きく書かれている。'],['a','「今日は、みんなで、新しいルールを、決めようと思います」'],['c','「{K}を、困らせないやつね！ ね？」']],
 [['','中庭のベンチ。女子たちが、お菓子を広げて、なにやら、作戦会議をしていた。'],['b','「あっ、{K}。いいところに。今、ちょうど、会議してたの」'],['a','「みんなで決めた約束を、聞いてほしいの」']]
];
function pactSlots(){return Math.min(6,1+Math.floor(haremN()/3))}
function pactList(){S.pacts=S.pacts||[];return S.pacts.map(id=>HG_PACTS.find(p=>p.id===id)).filter(Boolean)}
function pactMonthly(){
 const out=[];
 pactList().forEach(p=>{try{const t=p.f();if(t)out.push(t)}catch(e){}});
 if(out.length)NOTE=(NOTE?NOTE+'\n':'')+out.join('\n');
}
function pactMeeting(done){
 S.pacts=S.pacts||[];
 const gs=avail().slice().sort((a,b)=>favOf(b)-favOf(a)).slice(0,3);
 const cand=dShuffle(HG_PACTS.filter(p=>!S.pacts.includes(p.id))).slice(0,3);
 if(gs.length<3||!cand.length)return done&&done();
 S.pactT=S.t;S.pactN=(S.pactN||0)+1;cnt('meeting');
 const sc=HG_SCENES[Math.floor(Math.random()*HG_SCENES.length)].map(r=>r.slice());
 sc.forEach(r=>{if(r[1])r[1]=r[1].replace('{n}',S.pactN)});
 const L=[['cast','a,b,c']].concat(sc,[['c','「候補は、この三つ！ {K}も、いっしょに、選んでね」'],['a','「どれがいいと思う？ 一番、{K}らしいのを、お願い」']]);
 const girls=gs,lines=dailyApply({lines:L},girls,{N:haremN(),M:fcCount()});
 Novel.play({lines},{h:girls[0].id},()=>{
  show(girls[0].id,`【ハーレム会議】どの協定にする？\n(有効にできる協定の数: ${pactSlots()})`,
   cand.map(p=>[`${p.n}\n${p.d}`,()=>{
    S.pacts.push(p.id);while(S.pacts.length>pactSlots())S.pacts.shift();
    girls.forEach(h=>add(h.id,2));cnt('pact');
    NOTE=(NOTE?NOTE+'\n':'')+`【協定】「${p.n}」が、結ばれた。`;
    save();show(girls[0].id,dailyFmt(`「決まりだね！ これから、よろしくね、{K}」\n女子たちは、拍手をして、笑いあった。`,{},{}),[['つぎへ',()=>{done&&done()},'p']]);
   },'act','📜']).concat([['今回は、見送る',()=>{save();done&&done()},'act','💤']]));
 });
}
