function tripOffer(done){
 S.trip=S.trip||{};
 const key=yr()+'_'+mon();
 if(![3,8,12].includes(mon())||S.trip[key]||haremN()<5||S.t<6)return done&&done();
 const dests=HG_TRIPS.filter(d=>d.cost<=S.money&&(!d.m||d.m.includes(mon())));
 S.trip[key]=1;
 if(!dests.length)return done&&done();
 const gs=avail().slice().sort((a,b)=>favOf(b)-favOf(a)).slice(0,5);
 if(gs.length<5)return done&&done();
 const lines=dailyApply({lines:[['cast','a,b,c,d,e'],['','休み前の教室。{a}たちが、いっせいに、{K}の机を取り囲んだ。'],['a','「ねえ、{K}！ 今度の休み、みんなで、旅行に行かない？」'],['b','「もう、パンフレット、集めたの！」'],['c','「ね？ ね？ 行こうよ！」']]},gs,{N:haremN(),M:fcCount()});
 Novel.play({lines},{h:gs[0].id},()=>{
  show(gs[0].id,'【ハーレム旅行】みんなに、旅行に誘われた。どこに行く？',dests.map(d=>[`${d.n}\n費用 ${yen(d.cost)}`,()=>tripGo(d,gs,done),'act','🧳']).concat([['今回は、見送る',()=>{save();done&&done()},'act','💤']]));
 });
}
function tripGo(d,gs,done){
 S.money=Math.max(0,S.money-d.cost);
 const pk=a=>a[Math.floor(Math.random()*a.length)];
 const nights=pk(d.night),L=[['bg',d.bg],['cast','a,b,c,d,e,*6']].concat(pk(HG_TRIP_DEPART),pk(HG_TRIP_ROAD),[['','——'+d.n+'。']],pk(d.arrive),pk(d.act),[['','日が暮れて、夜になった。']],nights,pk(HG_TRIP_BACK),[['','旅行は、{K}にとって、かけがえのない、ひとつの思い出になった。']]);
 cnt('trip');cnt('trip_'+d.id);S.tripN=(S.tripN||0)+1;
 avail().forEach(h=>add(h.id,R(2,4)));gs.forEach(h=>add(h.id,2));
 gainSt('charm',R(1,2));
 const lines=dailyApply({lines:L},gs,{N:haremN(),M:fcCount()});
 Novel.play({lines},{h:gs[0].id},()=>{NOTE=(NOTE?NOTE+'\n':'')+`【旅の思い出】「${d.n}」(${S.tripN}回目)`;save();done&&done()});
}
/* 月替わりの流れに差しこむ */
const _keyEventPact=keyEvent;
keyEvent=function(done){
 if(!S||S.fin)return _keyEventPact(done);
 S.pacts=S.pacts||[];
 try{pactMonthly()}catch(e){}
 const next=()=>_keyEventPact(done);
 const due=haremN()>=3&&S.t>=6&&(S.pactT==null||S.t-S.pactT>=3);
 const afterMeet=()=>tripOffer(next);
 if(due)return pactMeeting(afterMeet);
 afterMeet();
};
