function hxInit(){S.hj=S.hj||{};S.han=S.han||{};S.pr=S.pr||{};}
function hxMonthly(done){
 hxInit();
 if(S.t<KE_FIRST_T||S.fin||S.hxT===S.t)return done&&done();
 const hm=(typeof HAREM_MIN!=='undefined'?HAREM_MIN:75),gs=avail();
 gs.forEach(h=>{if(favOf(h)>=hm&&S.hj[h.id]==null)S.hj[h.id]=S.t});
 /* ① 記念日 */
 const due=[];
 gs.forEach(h=>{if(S.hj[h.id]==null)return;[6,12,24,36].forEach(n=>{if(S.t-S.hj[h.id]>=n&&!S.han[h.id+':'+n])due.push([h,n])})});
 if(due.length&&Math.random()<.6){
  due.sort((a,b)=>b[1]-a[1]);const [h,n]=due[0];
  S.han[h.id+':'+n]=S.t;
  due.forEach(([g,m])=>{if(m<n&&g.id===h.id)S.han[g.id+':'+m]=S.t});
  S.hxT=S.t;cnt('anniv');
  const pool=HX_ANNIV[n],sc=pool[R(0,pool.length-1)],L=dailyApply({lines:sc},[h],{N:haremN(),M:fcCount()});
  add(h.id,3);S.money+=n>=24?50000:n>=12?20000:8000;gainSt('charm',n>=24?2:1);
  return Novel.play({lines:L},{h:h.id},()=>{save();done&&done()});
 }
 /* ② 女子同士 */
 if(Math.random()>=HX_P)return done&&done();
 const hi=gs.filter(h=>favOf(h)>=50);if(hi.length<2)return done&&done();
 const pairs=Object.keys(S.pr);let key=null;
 if(pairs.length&&Math.random()<.65){key=pairs[R(0,pairs.length-1)]}
 else{
  const a=hi[R(0,hi.length-1)],b=hi.filter(h=>h.id!==a.id)[R(0,hi.length-2)];
  if(!a||!b)return done&&done();
  key=[a.id,b.id].sort().join('|');
 }
 const [i1,i2]=key.split('|'),g1=H(i1),g2=H(i2);
 if(!g1||!g2||favOf(g1)<50||favOf(g2)<50)return done&&done();
 const p=S.pr[key]||(S.pr[key]={st:0,n:0});
 let pool;
 if(p.st===0)pool=HX_RIVAL;else if(p.st===1)pool=HX_TRUCE;else pool=(p.st>=2&&Math.random()<.4)?HX_DOUBLE:(Math.random()<.5?HX_FRIEND:HX_FRIEND.concat(HX_FRIEND2));
 const sc=pool[R(0,pool.length-1)],flip=Math.random()<.5,gg=flip?[g2,g1]:[g1,g2];
 p.n++;
 if(p.st===0&&p.n>=2){p.st=1;p.n=0}else if(p.st===1&&p.n>=2){p.st=2;p.n=0;cnt('bestfriend')}
 S.hxT=S.t;cnt('pairscene');
 if(pool===HX_DOUBLE){cnt('doubledate');add(g1.id,2);add(g2.id,2)}
 add(g1.id,1);add(g2.id,1);
 const L=dailyApply({lines:sc},gg,{N:haremN(),M:fcCount()});
 Novel.play({lines:L},{h:gg[0].id},()=>{save();done&&done()});
}
const _keyEventHx=keyEvent;
keyEvent=function(done){_keyEventHx(()=>hxMonthly(done))};


