function ltInit(){S.lt=S.lt||{n:0,read:0};S.lh=S.lh||[];}
function lettersTurn(){
 ltInit();
 const ch=S.st?S.st.charm:0;if(ch<30||S.fin)return;
 const n=Math.min(12,R(1,3)+Math.floor(ch/12)+Math.floor((typeof fcCount==='function'?fcCount():0)/300));
 S.lt.n=Math.min(LT_MAX,S.lt.n+n);
 NOTE=(NOTE?NOTE+'\n':'')+`【手紙】${n}通の手紙が届いた。(スマホの「手紙」アプリで読めます。未読 ${S.lt.n}通)`;
}
function ltOpenOne(){
 const gs=avail(),girl=gs.length&&Math.random()<.6?gs[R(0,gs.length-1)]:null;
 let who,txt,icon;
 if(girl){const f=favOf(girl),tier=f>=75?'high':f>=40?'mid':'low';who=girl.n;txt=LT_GIRL[tier][R(0,LT_GIRL[tier].length-1)];icon=girl.img}
 else{who='名前のないファン('+LT_FAN_NAME[R(0,LT_FAN_NAME.length-1)]+')';txt=LT_FAN[R(0,LT_FAN.length-1)];icon=String(R(1,170)).padStart(4,'0')}
 txt=dailyFmt(txt,{},{});
 const money=Math.round(R(200,1000)*(1+(S.st.charm||0)/60)/10)*10;
 let bonus='';
 if(Math.random()<.45){S.money+=money;bonus=`同封のおこづかい ${yen(money)}`}
 if(girl&&Math.random()<.1){add(girl.id,1)}
 if(Math.random()<.015){const g=gainSt('charm',1);if(g)bonus+=(bonus?'　':'')+'押し花のしおり(魅力+1)'}
 S.lt.read++;cnt('letter');
 const l={id:S.lt.read,who,txt,icon,bonus,gid:girl?girl.id:''};S.lh.unshift(l);S.lh=S.lh.slice(0,8);
 return l;
}
