function letReply(id,tone){
 ltInit();const l=S.lh.find(x=>String(x.id)===String(id));if(!l||l.rpt)return;
 tone=+tone;let t;
 if(l.gid&&H(l.gid)){t=LT_RP_GIRL[tone][R(0,LT_RP_GIRL[tone].length-1)];add(l.gid,2)}
 else{t=LT_RP_FAN[tone][R(0,LT_RP_FAN[tone].length-1)];if(Math.random()<.25)gainSt('charm',1);S.money+=500}
 l.rpt=dailyFmt(t,{},{});cnt('reply');save();
}
function letOpen(k){
 ltInit();k=Math.min(k,S.lt.n);if(k<=0)return;
 S.lt.n-=k;for(let i=0;i<k;i++)ltOpenOne();save();
}
function letHtml(){
 ltInit();
 let h=`<p class="hint">未読の手紙 ${S.lt.n} 通(これまでに読んだ手紙 ${S.lt.read} 通)。魅力が高いほど、たくさん届きます。</p>`;
 h+=`<button class="opt" type="button" ${S.lt.n>0?'data-do="letopen:1"':'disabled style="opacity:.45"'}>手紙を1通、開く</button>`;
 h+=`<button class="opt" type="button" ${S.lt.n>=5?'data-do="letopen:5"':'disabled style="opacity:.45"'}>5通まとめて、開く</button>`;
 h+=`<button class="opt" type="button" ${S.lt.n>=20?'data-do="letopen:20"':'disabled style="opacity:.45"'}>20通まとめて、開く(最新の8通が表示されます)</button>`;
 h+=S.lh.map(l=>`<div class="ev" style="display:block;border-left:3px solid #f43f5e;margin:8px 0;padding:6px 10px;background:rgba(244,63,94,.07)"><b style="display:flex;align-items:center;gap:8px"><img src="img/${l.icon}.jpg" alt="" width="30" height="30" style="border-radius:50%;object-fit:cover" onerror="this.style.display='none'">${l.who}より</b><span style="display:block;white-space:pre-wrap;margin-top:4px">${l.txt}</span>${l.bonus?`<span style="display:block;font-size:11px;opacity:.75">${l.bonus}</span>`:''}${l.rpt?`<span style="display:block;margin-top:6px;padding:4px 8px;border-radius:6px;background:rgba(255,255,255,.08);font-size:12px;white-space:pre-wrap">${l.rpt}</span>`:`<span style="display:flex;gap:6px;margin-top:6px">${['やさしく','ユーモアで','まじめに'].map((t,i)=>`<button type="button" class="opt" data-do="letrp:${l.id}:${i}" style="padding:2px 8px;font-size:11px">${t}返す</button>`).join('')}</span>`}</div>`).join('');
 return h;
}
