function ultraEvent(done){
 keInit();
 const all=avail().slice().sort((a,b)=>favOf(b)-favOf(a));
 if(all.length<5)return false;
 const ev=pickNR('ultraev',ULTRA_EVENTS);
 const girls=all.slice(0,Math.min(5,all.length));
 S.keN[S.t]=(S.keN[S.t]||0)+1;cnt('ultra');cnt('ultev');cnt('bigev');
 S.ultraSeen=S.ultraSeen||{};S.ultraSeen[ev.id]=1;
 const r=ev.rew||{};girls.forEach(h=>add(h.id,r.fav||0));
 if(r.all)all.forEach(h=>add(h.id,R(r.all[0],r.all[1])));
 if(r.money)S.money=Math.max(0,S.money+r.money);
 if(r.st)Object.keys(r.st).forEach(k=>gainSt(k,r.st[k]));
 const L=dailyApply({lines:ev.lines},girls,{N:haremN(),M:fcCount()});
 Novel.play({lines:L},{h:girls[0].id},()=>{save();done&&done()});
 return true;
}
const _bigEventUltra=bigEvent;
bigEvent=function(done){
 if(S&&S.st&&S.st.charm>=ULTRA_CHARM&&Math.random()<ULTRA_P&&(S.keN&&(S.keN[S.t]||0)<KE_PER_MONTH)){
  if(ultraEvent(done))return;
 }
 return _bigEventUltra(done);
};
